package com.silverroom.camera;
import org.json.*;

final class SettingsCodec {
    static JSONObject write(Film.Settings s)throws JSONException{JSONObject j=new JSONObject();j.put("stock",s.stock);j.put("temperature",s.temperature);j.put("strength",s.strength);j.put("cyan",s.cyan);j.put("magenta",s.magenta);j.put("yellow",s.yellow);j.put("exposure",s.exposure);j.put("grain",s.grain);j.put("fade",s.fade);j.put("skin",s.skin);j.put("highlights",s.highlights);j.put("adaptive_grain",s.adaptiveGrain);j.put("iso",s.iso);j.put("grain_edge",s.grainEdge);j.put("red",s.red);j.put("green",s.green);j.put("blue",s.blue);j.put("contrast",s.contrast);j.put("calibration_ev",s.calibrationEv);return j;}
    static float value(JSONObject j,String key,float fallback,float lo,float hi){return ImageQuality.clamp((float)j.optDouble(key,fallback),lo,hi);}
    static Film.Settings read(JSONObject j){Film.Settings s=new Film.Settings();s.stock=FilmCatalog.safe(j.optInt("stock",1));s.temperature=value(j,"temperature",0,-1,1);s.strength=value(j,"strength",1,0,1);s.cyan=value(j,"cyan",0,-1,1);s.magenta=value(j,"magenta",0,-1,1);s.yellow=value(j,"yellow",0,-1,1);s.exposure=value(j,"exposure",0,-2,2);s.grain=value(j,"grain",.2f,0,1);s.fade=value(j,"fade",.1f,0,1);s.skin=value(j,"skin",0,0,1);s.highlights=value(j,"highlights",0,0,1);s.adaptiveGrain=j.optBoolean("adaptive_grain",false);s.iso=Math.max(0,j.optInt("iso",0));s.grainEdge=Math.max(1,Math.min(4096,j.optInt("grain_edge",4096)));s.red=value(j,"red",1,.85f,1.15f);s.green=value(j,"green",1,.85f,1.15f);s.blue=value(j,"blue",1,.85f,1.15f);s.contrast=value(j,"contrast",1,.9f,1.1f);s.calibrationEv=value(j,"calibration_ev",0,-.5f,.5f);return s;}
}
